(async()=>{try{const api=await import('./checkpoint-sequence.js?v=motion-v89');if(!window.motionOpportunityReady)await new Promise(r=>window.addEventListener('motion-opportunity-ready',r,{once:true}));for(const[k,v]of Object.entries(api.checkpointDefaults))if(fx[k]===undefined)fx[k]=structuredClone(v);const oldPhases=phaseTimes,oldFrame=frame,oldControls=renderDepotControls,seconds=t*settings.duration,start=()=>oldPhases().end;for(const[k,file]of Object.entries(api.checkpointSources)){sources[k]='assets/'+file;if(!sprites[k]){const im=new Image();im.onload=()=>{base._renderKey='';};im.src=sources[k];sprites[k]=im;}}restoreAssets();globalThis.motionTagSources?.();phaseTimes=()=>{const p=oldPhases();return{...p,end:p.end+(fx.checkpointEnabled?api.checkpointDuration(fx):0)}};
frame=function(el,p){const duration=settings.duration,time=p*duration,prior=phaseTimes;try{phaseTimes=oldPhases;settings.duration=oldPhases().end;oldFrame(el,Math.min(time,settings.duration-.000001)/settings.duration);}finally{phaseTimes=prior;settings.duration=duration;}let canvas=el.querySelector('.documentaryCheckpoint');if(!fx.checkpointEnabled||time<start()){if(canvas)canvas.style.display='none';return;}if(!canvas){canvas=document.createElement('canvas');canvas.width=960;canvas.height=540;canvas.className='tearCanvas documentaryCheckpoint';canvas.style.cssText='position:absolute;inset:0;width:100%;height:100%;pointer-events:none;z-index:55';el.append(canvas);}canvas.style.display='block';for(const slot of Object.keys(api.checkpointSources)){const media=sprites[fx.checkpointSourceBindings[slot]||slot];if(media?.tagName==='VIDEO'&&media.readyState>=2){const target=Math.max(0,api.checkpointState(time-start(),fx).source-895)%Math.max(.01,media.duration);if(Math.abs(media.currentTime-target)>.08)media.currentTime=target;}}api.paintCheckpoint(canvas.getContext('2d'),Math.min(time-start(),api.checkpointDuration(fx)),sprites,fx);};
function refresh(){api.validateCheckpoint(fx);const sec=t*settings.duration;syncDuration();t=Math.min(1,sec/settings.duration);saveEffects();base._renderKey='';frame(base,t);}function seek(source){openEditor();playing=false;t=(start()+api.checkpointSourceToLocal(source,fx))/settings.duration;frame(base,t);const scrub=document.querySelector('#scrub');if(scrub)scrub.value=t*1000;}
renderDepotControls=function(){oldControls();const host=document.querySelector('#depotControls');if(!host)return;const box=document.createElement('details');box.className='directorSection';box.innerHTML='<summary>V89 native humanoid / V88 fallback ·14:55–15:00</summary>';host.prepend(box);const previews=document.createElement('div');previews.className='directorGrid';for(const s of api.checkpointStages){const b=document.createElement('button');b.className='pill';b.textContent=s.label;b.onclick=()=>seek((s.from+s.to)/2);previews.append(b);}box.append(previews);
const json=document.createElement('textarea');json.value=JSON.stringify(Object.fromEntries(Object.keys(api.checkpointDefaults).map(k=>[k,fx[k]])),null,2);json.setAttribute('aria-label','Checkpoint scene settings');const apply=document.createElement('button');apply.className='pill';apply.textContent='Apply scene settings';apply.onclick=()=>{try{const v=JSON.parse(json.value);api.validateCheckpoint(v);for(const k of Object.keys(api.checkpointDefaults))if(v[k]!==undefined)fx[k]=structuredClone(v[k]);refresh();renderDepotControls();}catch(e){apply.textContent=e.message;}};box.append(json,apply);
const select=document.createElement('select');for(const l of api.checkpointLayerCatalog)select.add(new Option(l.label,l.id));const edits=document.createElement('textarea'),update=document.createElement('button');update.className='pill';update.textContent='Apply selected object motion';function read(){edits.value=JSON.stringify(fx.checkpointLayerEdits[select.value]||{visible:true,x:0,y:0,scale:1,rotation:0,opacity:1,blur:0,depth:2,motion:{}},null,2);}select.onchange=read;read();update.onclick=()=>{try{const v=JSON.parse(edits.value),next={...fx.checkpointLayerEdits,[select.value]:v};api.validateCheckpoint({...fx,checkpointLayerEdits:next});fx.checkpointLayerEdits=next;refresh();}catch(e){update.textContent=e.message;}};box.append(select,edits,update);
const replace=document.createElement('button');replace.className='pill';replace.textContent='Replace selected picture/video';replace.onclick=()=>{const slot=api.checkpointLayerCatalog.find(l=>l.id===select.value)?.slot;if(!slot)return;const picker=document.createElement('input');picker.type='file';picker.accept='image/*,video/*';picker.onchange=async()=>{const file=picker.files[0];if(!file)return;const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file)});const prior=sprites[slot]?.src;if(prior&&prior!==sources[slot]){const key=slot+'-archive-'+Date.now();await saveAsset(key,prior);(fx.checkpointReplacementHistory??=[]).push({slot,key});}if(file.type.startsWith('video/')){const v=document.createElement('video');v.muted=true;v.playsInline=true;v.preload='auto';v.src=data;v.onloadeddata=refresh;v.onseeked=()=>frame(base,t);sprites[slot]=v;}else{const im=new Image();im.onload=refresh;im.src=data;sprites[slot]=im;}fx.checkpointSourceBindings[slot]=slot;await saveAsset(slot,data);refresh();};picker.click();};box.append(replace);const note=document.createElement('p');note.className='sub';note.textContent='V88 connected skinned bodies. Edit roots/camera/light and joint keys in scene JSON. Set checkpointRefinementEnabled:false for preserved V87. Exported glTF scenes in assets/models retain independent bones and props. Native smoke, hands and acting remain approximate.';box.append(note);};renderDepotControls();syncDuration();t=Math.min(1,seconds/settings.duration);saveEffects();window.MotionCheckpoint={...api,start,seek};registerCapability('doc-checkpoint',{label:'Final five seconds to15:00',category:'Documentary actions',defaults:api.checkpointDefaults,slots:Object.keys(api.checkpointSources),render:(c,age,layer)=>api.paintCheckpoint(c,age,sprites,{...fx,...layer.params})});window.motionCheckpointReady=true;window.dispatchEvent(new Event('motion-checkpoint-ready'));}catch(e){console.error('Checkpoint continuation',e);}})();
